import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.DNL3hc5c.js";const f=JSON.parse('{"title":"Weekday Parsing","description":"","frontmatter":{},"headers":[],"relativePath":"doc/4-advanced-reference/tempo.weekday.md","filePath":"doc/4-advanced-reference/tempo.weekday.md"}'),o={name:"doc/4-advanced-reference/tempo.weekday.md"};function s(l,e,n,r,c,h){return a(),i("div",null,[...e[0]||(e[0]=[d(`<h1 id="weekday-parsing" tabindex="-1">Weekday Parsing <a class="header-anchor" href="#weekday-parsing" aria-label="Permalink to &quot;Weekday Parsing&quot;">​</a></h1><p>Tempo provides a flexible way to parse Weekday inputs, allowing you to specify dates relative to the current day or a specific base date. This is particularly useful for phrases like &quot;next Monday&quot; or &quot;3 Wednesdays ago&quot;.</p><h2 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h2><p>Weekday inputs typically consist of a <strong>modifier</strong> (optional), a <strong>count</strong> (optional), and the <strong>Weekday name</strong>.</p><h3 id="_1-simple-weekday-names" tabindex="-1">1. Simple Weekday Names <a class="header-anchor" href="#_1-simple-weekday-names" aria-label="Permalink to &quot;1. Simple Weekday Names&quot;">​</a></h3><p>You can provide the short or full name of a Weekday.</p><ul><li><code>Mon</code>, <code>Monday</code></li><li><code>Wed</code>, <code>Wednesday</code></li><li><code>Sun</code>, <code>Sunday</code></li></ul><h3 id="_2-symbolic-modifiers" tabindex="-1">2. Symbolic Modifiers <a class="header-anchor" href="#_2-symbolic-modifiers" aria-label="Permalink to &quot;2. Symbolic Modifiers&quot;">​</a></h3><p>Symbols can be used to indicate relative weeks or specific directions in time.<br> When no modifier is provided, Tempo defaults to the Weekday in the <strong>current week</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Modifier</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Example</th><th style="text-align:left;">Results in...</th></tr></thead><tbody><tr><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">Next week</td><td style="text-align:left;"><code>+Mon</code></td><td style="text-align:left;">Monday of next week</td></tr><tr><td style="text-align:left;"><code>-</code></td><td style="text-align:left;">Previous week</td><td style="text-align:left;"><code>-Tue</code></td><td style="text-align:left;">Tuesday of last week</td></tr><tr><td style="text-align:left;"><code>&lt;=</code></td><td style="text-align:left;">Prior to</td><td style="text-align:left;"><code>&lt;=Wed</code></td><td style="text-align:left;">The Wednesday immediately preceding (or equal to) today</td></tr><tr><td style="text-align:left;"><code>&lt;</code></td><td style="text-align:left;">Prior to (strict)</td><td style="text-align:left;"><code>&lt;Thu</code></td><td style="text-align:left;">The Thursday strictly before today</td></tr><tr><td style="text-align:left;"><code>&gt;=</code></td><td style="text-align:left;">Subsequent to</td><td style="text-align:left;"><code>&gt;=Fri</code></td><td style="text-align:left;">The Friday immediately following (or equal to) today</td></tr><tr><td style="text-align:left;"><code>&gt;</code></td><td style="text-align:left;">Subsequent to (strict)</td><td style="text-align:left;"><code>&gt;Sat</code></td><td style="text-align:left;">The Saturday strictly after today</td></tr></tbody></table><h3 id="strict-vs-inclusive-boundaries" tabindex="-1">Strict vs Inclusive Boundaries <a class="header-anchor" href="#strict-vs-inclusive-boundaries" aria-label="Permalink to &quot;Strict vs Inclusive Boundaries&quot;">​</a></h3><p>The difference between <code>&lt;</code> (strict) and <code>&lt;=</code> (inclusive) is only relevant when you evaluate a string on the exact same weekday you are targeting.</p><p>For example, if today is <strong>Wednesday</strong>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;Wed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → returns LAST Wednesday (strictly before today)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;=Wed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → returns TODAY (inclusive match)</span></span></code></pre></div><h3 id="_3-keyword-modifiers" tabindex="-1">3. Keyword Modifiers <a class="header-anchor" href="#_3-keyword-modifiers" aria-label="Permalink to &quot;3. Keyword Modifiers&quot;">​</a></h3><p>Keywords can be used for more natural language-like inputs.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Keyword</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>this</code></td><td style="text-align:left;">Current week</td><td style="text-align:left;"><code>this Wed</code></td></tr><tr><td style="text-align:left;"><code>next</code></td><td style="text-align:left;">Next week</td><td style="text-align:left;"><code>next Monday</code></td></tr><tr><td style="text-align:left;"><code>prev</code></td><td style="text-align:left;">Previous week</td><td style="text-align:left;"><code>prev Fri</code></td></tr><tr><td style="text-align:left;"><code>last</code></td><td style="text-align:left;">Last week</td><td style="text-align:left;"><code>last Sunday</code></td></tr></tbody></table><h3 id="_4-count-modifiers" tabindex="-1">4. Count Modifiers <a class="header-anchor" href="#_4-count-modifiers" aria-label="Permalink to &quot;4. Count Modifiers&quot;">​</a></h3><p>You can specify a number of weeks to jump by adding a count after the modifier.</p><ul><li><code>-3 Wed</code>: Three Wednesdays ago</li><li><code>+2 Mon</code>: Two Mondays from now</li></ul><h3 id="_5-relative-suffixes" tabindex="-1">5. Relative Suffixes <a class="header-anchor" href="#_5-relative-suffixes" aria-label="Permalink to &quot;5. Relative Suffixes&quot;">​</a></h3><p>You can also specify the direction of time using a suffix.</p><ul><li><code>3 Wed ago</code>: Three Wednesdays ago</li><li><code>2 Mon hence</code>: Two Mondays hence</li><li><code>2 Mon from now</code>: Two Mondays from now</li></ul><h2 id="time-suffixes" tabindex="-1">Time Suffixes <a class="header-anchor" href="#time-suffixes" aria-label="Permalink to &quot;Time Suffixes&quot;">​</a></h2><p>You can append time information to a Weekday string. Tempo will parse the Weekday first and then apply the time to that specific date.</p><ul><li><code>Mon 10:00am</code></li><li><code>&gt;Friday noon</code></li><li><code>&lt;3 Wed 15:30:00</code></li></ul><h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><ol><li><strong>Normalization</strong>: Weekday names are normalized to their 3-letter proper-case prefix (e.g., <code>monday</code> -&gt; <code>Mon</code>).</li><li><strong>Anchor</strong>: If no time-zone or base date is provided, Tempo uses &quot;now&quot; as the anchor.</li><li><strong>Calculation</strong>: The modifier and count determine the number of weeks to add or subtract from the anchor date to find the target Weekday.</li><li><strong>Constraint</strong>: If time components are provided, they are set on the calculated date. Otherwise, the time defaults to <code>00:00:00</code> if it&#39;s the first parsing pass.</li></ol>`,28)])])}const p=t(o,[["render",s]]);export{f as __pageData,p as default};
